import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid session token."""
    token = request.headers.get('X-Session-Token')
    if not token or len(token) < 32:
        return jsonify({'error': 'unauthorized'}), 401

    department = request.args.get('dept', '')
    role_filter = request.args.get('role', '')

    # Build query with department filter
    base_query = "SELECT id, username, email, department, role FROM users WHERE department = '" + department + "'"

    if role_filter:
        base_query += " AND role = '" + role_filter + "'"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)",
            ('user_search', token[:8], department)
        )
        db.commit()
        return jsonify({'users': results})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID."""
    token = request.headers.get('X-Session-Token')
    if not token or len(token) < 32:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute(
        "SELECT id, username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()

    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create new user. Admin only."""
    token = request.headers.get('X-Session-Token')
    if not token or len(token) < 32:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    username = data.get('username', '')
    email = data.get('email', '')
    department = data.get('department', '')
    password = data.get('password', '')

    if not all([username, email, department, password]):
        return jsonify({'error': 'missing fields'}), 400

    password_hash = hashlib.sha256(password.encode()).hexdigest()

    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (username, password_hash, email, department) VALUES (?, ?, ?, ?)",
            (username, password_hash, email, department)
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
